#include <cstring>
#include <string>

extern "C" int describe_into(int stones, char* buffer, int capacity)
{
    const std::string text{ std::to_string(stones) + (stones == 1 ? " stone" : " stones") };
    const int length{ static_cast<int>(text.size()) };
    if (buffer && capacity >= 1)
    {
        const int copy{ length < capacity - 1 ? length : capacity - 1 };
        std::memcpy(buffer, text.data(), static_cast<std::size_t>(copy));
        buffer[copy] = '\0';
    }
    return length;
}

unitTests:
TEST("ask for the size") { CHECK_EQ(describe_into(12, nullptr, 0), 9); CHECK_EQ(describe_into(1, nullptr, 0), 7); }
TEST("big enough") { char b[32]; CHECK_EQ(describe_into(12, b, 32), 9); CHECK_EQ(std::string(b), std::string("12 stones")); }
TEST("exactly big enough") { char b[10]; CHECK_EQ(describe_into(12, b, 10), 9); CHECK_EQ(std::string(b), std::string("12 stones")); }
TEST("one too small") { char b[9]; CHECK_EQ(describe_into(12, b, 9), 9); CHECK_EQ(std::string(b), std::string("12 stone")); }
TEST("tiny buffer") { char b[4]; CHECK_EQ(describe_into(12, b, 4), 9); CHECK_EQ(std::string(b), std::string("12 ")); }
TEST("capacity one") { char b[1] = { 'x' }; CHECK_EQ(describe_into(5, b, 1), 8); CHECK_EQ(b[0], '\0'); }
TEST("one stone") { char b[16]; describe_into(1, b, 16); CHECK_EQ(std::string(b), std::string("1 stone")); }
TEST("nothing written for capacity 0") { char b[2] = { 'x', 'y' }; describe_into(5, b, 0); CHECK_EQ(b[0], 'x'); }

